/*
 * Frontend demo data adapter
 *
 * The original project called an Express/MongoDB API. This adapter preserves
 * the small axios-like interface used by the UI, but stores seeded demo data
 * in localStorage so the portfolio build runs without a server.
 */
const STORAGE_KEY = 'nostruggle:frontend-demo-data';
const now = () => new Date().toISOString();
const id = (prefix) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;

const initialData = () => ({
  users: [
    { _id: 'demo-user', username: 'demo', password: 'demo', aboutMe: 'Computer science student focused on building practical study tools.' },
    { _id: 'maya-user', username: 'maya', password: 'demo', aboutMe: 'I enjoy breaking down tricky algorithms.' },
    { _id: 'leo-user', username: 'leo', password: 'demo', aboutMe: 'Always happy to compare study strategies.' }
  ],
  posts: [
    { _id: 'post-graphs', title: 'How do you approach graph traversal?', content: 'I understand BFS and DFS separately, but I am looking for a practical way to decide which one fits a problem.', tags: 'Algorithms', created_by: 'maya', created_At: '2026-08-29T14:00:00.000Z', updated: '2026-08-29T14:00:00.000Z', nLikes: 2, likedBy: ['demo', 'leo'] },
    { _id: 'post-exams', title: 'What is your exam-week study routine?', content: 'Looking for a sustainable schedule that balances practice problems, breaks, and sleep.', tags: 'Study Tips', created_by: 'leo', created_At: '2026-09-01T16:30:00.000Z', updated: '2026-09-01T16:30:00.000Z', nLikes: 1, likedBy: ['maya'] },
    { _id: 'post-react', title: 'Helpful way to organize a React feature?', content: 'What patterns help keep components, state, and feature-specific logic understandable as an app grows?', tags: 'Web Development', created_by: 'demo', created_At: '2026-09-03T10:15:00.000Z', updated: '2026-09-03T10:15:00.000Z', nLikes: 3, likedBy: ['maya', 'leo', 'demo'] }
  ],
  answers: [
    { _id: 'answer-1', child_of: 'post-graphs', content: 'Start from the problem constraints: BFS is excellent for shortest paths in an unweighted graph, while DFS is useful for exploring structure and connectivity.', created_by: 'leo', created_At: '2026-08-30T09:00:00.000Z', nLikes: 1, likedBy: ['maya'] },
    { _id: 'answer-2', child_of: 'post-react', content: 'I group code by feature first, then keep reusable UI components separate. It makes ownership and imports much clearer.', created_by: 'maya', created_At: '2026-09-04T11:30:00.000Z', nLikes: 2, likedBy: ['demo', 'leo'] }
  ], comments: [],
  tasks: [
    { _id: 'task-1', userId: 'demo-user', title: 'Review graph algorithms', deadline: '2026-09-10T00:00:00.000Z', timespent: 5400, done: false, archived: false },
    { _id: 'task-2', userId: 'demo-user', title: 'Finish React component notes', deadline: '2026-09-08T00:00:00.000Z', timespent: 2700, done: true, archived: false },
    { _id: 'task-3', userId: 'demo-user', title: 'Practice interview questions', deadline: '2026-09-12T00:00:00.000Z', timespent: 1800, done: false, archived: false }
  ],
  daily: [{ _id: 'daily-1', userId: 'demo-user', taskId: 'task-1', timespent: 5400, date: now() }, { _id: 'daily-2', userId: 'demo-user', taskId: 'task-2', timespent: 2700, date: now() }],
  notifications: [{ _id: 'notification-1', userId: 'demo-user', type: 'answer', sender: 'maya', title: 'Helpful way to organize a React feature?', postId: 'post-react', read: false, created_At: now() }]
});

const read = () => { try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || initialData(); } catch { return initialData(); } };
const write = (data) => localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
const response = (data, status = 200) => Promise.resolve({ data, status });
const pathInfo = (url) => { const parsed = new URL(url, 'http://demo.local'); return { path: parsed.pathname.replace(/\/+$/, ''), query: parsed.searchParams }; };
const updateById = (items, itemId, changes) => { const item = items.find((entry) => entry._id === itemId); if (item) Object.assign(item, changes, { updated: now() }); return item; };

function get(url) {
  const { path, query } = pathInfo(url); const data = read();
  if (path === '/forumPosts/get') { const username = query.get('created_by'); return response(username ? data.posts.filter((post) => post.created_by === username) : data.posts); }
  if (path.startsWith('/forumPosts/')) return response(data.posts.find((post) => post._id === path.split('/').pop()) || {});
  if (path.startsWith('/postThread/answers/')) return response(data.answers.filter((answer) => answer.child_of === path.split('/')[3]));
  if (path.startsWith('/postThread/')) return response(data.posts.find((post) => post._id === path.split('/')[2]) || {});
  if (path === '/postThread') return response(data.answers.filter((answer) => answer.created_by === query.get('created_by')), 201);
  if (path.startsWith('/comment/get/')) return response(data.comments.filter((comment) => comment.child_of === path.split('/').pop()));
  if (path.startsWith('/users/get/')) { const [, , , username, password] = path.split('/'); return response(data.users.filter((user) => user.username === username && user.password === password)); }
  if (path.startsWith('/users/username/')) return response(data.users.filter((user) => user.username === path.split('/').pop()));
  if (path.startsWith('/users/aboutme/')) { const user = data.users.find((entry) => entry.username === path.split('/').pop()); return response([{ username: user?.username, content: user?.aboutMe || '' }]); }
  if (path === '/tasks') { let tasks = data.tasks.filter((task) => task.userId === query.get('userId')); if (query.has('done')) tasks = tasks.filter((task) => String(task.done) === query.get('done')); return response(tasks); }
  if (path === '/tasks/daily' || path === '/tasks/daily/date') return response(data.daily.filter((entry) => entry.userId === query.get('userId')));
  if (path === '/notification/new') return response({ hasNewNotifications: data.notifications.some((entry) => entry.userId === query.get('userId') && !entry.read) });
  if (path === '/notification/pagecount') return response({ pageCount: 1 });
  if (path.startsWith('/notification/page/')) return response(data.notifications.filter((entry) => entry.userId === query.get('userId')));
  if (path === '/notification') return response(data.notifications.filter((entry) => entry.userId === query.get('userId')));
  return response([]);
}

function post(url, body = {}) {
  const { path, query } = pathInfo(url); const data = read();
  if (path === '/users/post') { if (data.users.some((user) => user.username === body.username)) return Promise.reject({ response: { data: { message: 'That username is already in use.' } } }); const user = { _id: id('user'), ...body, aboutMe: '' }; data.users.push(user); write(data); return response(user, 201); }
  if (path === '/forumPosts/post') { const post = { _id: id('post'), ...body, created_At: now(), updated: now(), nLikes: 0, likedBy: [] }; data.posts.push(post); write(data); return response(post, 201); }
  if (path === '/answers/post') { const answer = { _id: id('answer'), ...body, created_At: now(), nLikes: 0, likedBy: [] }; data.answers.push(answer); write(data); return response(answer, 201); }
  if (path === '/comment/post') { const comment = { _id: id('comment'), ...body, created_At: now() }; data.comments.push(comment); write(data); return response(comment, 201); }
  if (path === '/tasks') { const task = { _id: id('task'), ...body, archived: false }; data.tasks.push(task); write(data); return response(task, 201); }
  if (path === '/tasks/daily') { const entry = { _id: id('daily'), userId: query.get('userId'), taskId: query.get('taskId'), timespent: Number(query.get('timespent') || 0), date: now() }; data.daily.push(entry); const task = data.tasks.find((item) => item._id === entry.taskId); if (task) task.timespent += entry.timespent; write(data); return response(entry, 201); }
  if (path === '/notification') { const notification = { _id: id('notification'), ...body, read: false, created_At: now() }; data.notifications.push(notification); write(data); return response(notification, 201); }
  if (path === '/notification/read') { const notification = data.notifications.find((entry) => entry._id === query.get('notificationId')); if (notification) notification.read = true; write(data); return response(notification); }
  return response(body, 201);
}

function patch(url, body = {}) { const { path } = pathInfo(url); const data = read(); let result; if (path === '/tasks') result = updateById(data.tasks, body.filters?._id, body.update || {}); else if (path.startsWith('/forumPosts/')) result = updateById(data.posts, path.split('/').pop(), body); else if (path.startsWith('/postThread/patch/')) result = updateById(data.answers, path.split('/').pop(), body); write(data); return response(result || {}); }
function put(url, body = {}) { const { path } = pathInfo(url); const data = read(); if (path.startsWith('/users/aboutme/')) { const user = data.users.find((entry) => entry.username === path.split('/').pop()); if (user) user.aboutMe = body.content; write(data); return response(body); } return response(body); }
function remove(url) { const { path } = pathInfo(url); const data = read(); if (path.startsWith('/forumPosts/')) data.posts = data.posts.filter((post) => post._id !== path.split('/').pop()); write(data); return response({}); }

function ApiCall(url) { return get(url); }
ApiCall.get = get; ApiCall.post = post; ApiCall.patch = patch; ApiCall.put = put; ApiCall.delete = remove;
export default ApiCall;
